			"top-level field with UTF8",
			`["field with ÜFT8👌"]`,
			[]interface{}{"field with ÜFT8👌"},
			nil,
		},
		{
			"top-level array access",
			`[0]`,
			[]interface{}{0},
			nil,
		},
		{
			"nested field",
			`pod.uuid`,
			[]interface{}{"pod", "uuid"},
			nil,
		},
		{
			"nested field alternate syntax",
			`pod["uuid"]`,
			[]interface{}{"pod", "uuid"},
			nil,
		},
